//! Literal residual entries for the SAME algebraic witness as R37--R39.
include!("r37_residual_arithmetic.rs");
fn base(n:u32)->K{K::ONE.mul_m31(M31(n))}
fn residue(v:K)->u32{let mut b=[0;16];v.write_le_bytes(&mut b);assert_eq!(&b[4..],&[0;12]);u32::from_le_bytes(b[..4].try_into().unwrap())}
fn residues(p:&[K])->Vec<u32>{p.iter().map(|&v|residue(v)).collect()}
fn main(){
    let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);assert!(args[1]=="--write"||args[1]=="--check");let out=std::path::Path::new(&args[2]);let checking=args[1]=="--check";
    if !checking{assert!(!out.exists());std::fs::create_dir(out).unwrap();}
    let z=std::array::from_fn(|i|base(i as u32+2));let abc=[base(7),base(5),base(5).neg()];let k=base(5);let alpha=base(7);let map=basis_transport::transport();
    assert_eq!(map.order.as_slice(),&fixed::ORDER);assert_eq!(map.inactive.as_slice(),&fixed::INACTIVE);
    let mut p=vec![K::ONE];for r in 1..23{let mut n=times_x(&p);for j in 0..p.len(){n[j]=n[j].sub(base(r).mul(p[j]));}p=n;}assert_eq!(p.len(),23);
    let mut ew=[[K::ZERO;108];3];let source_points=corelib::v6_transcript::v6_statement_points(&z);let mut point_weights=Vec::new();
    for i in 0..3{assert_eq!(point(&z,i),source_points[i]);let mut w=WeightAccumulator::empty(10);w.add_multilinear(K::ONE,source_points[i].to_vec()).unwrap();let dense:Vec<_>=(0..1024).map(|r|w.weight_at(r)).collect();let e=opening_weights::chord_transpose(&map.dual(&dense),abc);ew[i].copy_from_slice(&e[..108]);point_weights.push(dense);}
    let wr:[K;108]=std::array::from_fn(|r|k.mul(ew[0][r]).add(k.pow(2).mul(ew[1][r])).add(k.pow(3).mul(ew[2][r])));
    let wg:[K;108]=std::array::from_fn(|r|k.pow(2).mul(ew[1][r]).add(k.pow(3).mul(ew[2][r])));
    let rw=opening_weights::quotient_weights(&z,k,abc,base(17),false);let gw=opening_weights::quotient_weights(&z,k,abc,base(17),true);
    for r in 0..108{assert_eq!(wr[r],rw.weight_at(r as u32));assert_eq!(wg[r],gw.weight_at(r as u32));}
    let mut qs=Vec::new();let mut obs=Vec::new();let rows=[1,2,3,4,5,6,7,8,10,11,12,13,15];let mut source_v=p.clone();let mut negative=0;
    for c in 0..13{if c>0&&c%3==0{source_v=times_x(&source_v);}let q=quotient(&p,c,alpha);let mut full=vec![K::ZERO;1024];for(j,&v)in source_v.iter().enumerate(){full[4*j+c%3+1]=v;full[4*j]=alpha.pow((c%3+1)as u64).mul(v).neg();}assert_eq!(&full[..108],q.as_slice());assert!(full[108..].iter().all(|&v|v==K::ZERO));
        let original=map.inverse(&chord(&full,abc));assert!(structured_g::mixed_coins(&original).iter().all(|&v|v==K::ZERO));let mut o=vec![K::ZERO,dot(&q,&ew[1]),dot(&q,&ew[2])];for i in 1..3{assert_eq!(o[i],dot(&original,&point_weights[i]));}let pr=poly(&q,&wr,true);let pg=poly(&q,&wg,true);assert_eq!(pr,polynomial_for_extension(&full,&rw));assert_eq!(pg,polynomial_for_extension(&full,&gw));if poly(&q,&wr,false)!=pr{negative+=1;}o.extend(pr);o.extend(pg);qs.push(q);obs.push(o);
    }assert_eq!(negative,13);
    let prior=std::fs::read(&args[3]).unwrap();let mut encoded=Vec::new();for &r in &rows{for c in 0..13{let mut b=[0;16];obs[c][r].write_le_bytes(&mut b);encoded.extend(b);}}assert_eq!(encoded,prior,"R37 witness drift");
    let header="/- Generated staged residual-entry certificate. -/\n";let ns="namespace AspisR19.WitnessEntryData\nopen RootCertificate ResidualModel ResidualEntryCertificate\nnoncomputable section\n";let end="end\nend AspisR19.WitnessEntryData\n";let mut files=std::collections::BTreeMap::<String,String>::new();
    let mut data=format!("{header}import AspisV8R19.ResidualEntryCertificate\nimport AspisV8R19.WitnessPointBridge\nimport AspisV8R19.WitnessRootBridge\n{ns}def quarter : M := 536870912\ndef wr : Fin 108 → M := PointWeightCertificate.vector {:?}\ndef wg : Fin 108 → M := PointWeightCertificate.vector {:?}\n",residues(&wr),residues(&wg));
    for c in 0..13{data+=&format!("def q{c} : Fin 108 → M := PointWeightCertificate.vector {:?}\n",residues(&qs[c]));}
    data+="def matrix : Matrix (Fin 13) (Fin 13) M := fun i j =>\n  ((";data+=&format!("{:?}",rows.iter().map(|&r|(0..13).map(|c|residue(obs[c][r])).collect::<Vec<_>>()).collect::<Vec<_>>());data+=" : List (List Nat)).getD i.val []).getD j.val 0\n";data+=end;files.insert("WitnessEntryData.lean".into(),data);
    let mut inputs=format!("{header}import AspisV8R19.WitnessEntryData\n{ns}theorem padding : (fun j : Fin 27 => if h : j.val<23 then SourceResidualPolynomial.rootCoefficients half WitnessRootData.roots ⟨j.val,h⟩ else 0) = WitnessRootData.p22 := by\n  simp only [WitnessRootData.root_coefficients]\n  funext j\n  fin_cases j <;> decide\n");
    for (name,expr)in[("wr","(5:M)*WitnessPointData.weights0 r+5^2*WitnessPointData.weights1 r+5^3*WitnessPointData.weights2 r"),("wg","(5:M)^2*WitnessPointData.weights1 r+5^3*WitnessPointData.weights2 r")]{inputs+=&format!("theorem {name}_stage : (fun r => {expr}) = {name} := by\n  funext r\n  fin_cases r <;> decide\n#print axioms {name}_stage\n");}inputs+="#print axioms padding\n";inputs+=end;files.insert("WitnessEntryInputs.lean".into(),inputs);
    let mut bridge=String::from(header);
    for c in 0..13{
        let mut qproof=format!("{header}import AspisV8R19.WitnessEntryInputs\n{ns}theorem quotient{c} : quotient half (7:M) (SourceResidualPolynomial.rootCoefficients half WitnessRootData.roots) ({c}:Fin 13) = q{c} := by\n  unfold quotient\n  rw [padding]\n  have hs : shift half (({c}:Fin 13).val/3) WitnessRootData.p22 = WitnessRootData.s{} := WitnessRootData.shift{}\n  simp only [hs]\n  funext r\n  fin_cases r <;> decide\n#print axioms quotient{c}\n{end}",c/3,c/3);files.insert(format!("WitnessQuotient{c:02}.lean"),std::mem::take(&mut qproof));
        let mut body=format!("{header}import AspisV8R19.WitnessQuotient{c:02}\n{ns}");
        for which in 1..3{
            for chunk in 0..4{let part=dot(&qs[c][chunk*27..(chunk+1)*27],&ew[which][chunk*27..(chunk+1)*27]);let idx=if chunk==0{"j.val".into()}else{format!("{}+j.val",chunk*27)};body+=&format!("theorem dot{c}_{which}_{chunk} : (∑ j : Fin 27, q{c} ⟨{idx},by omega⟩ * WitnessPointData.weights{which} ⟨{idx},by omega⟩) = ({}:M) := by decide\n#print axioms dot{c}_{which}_{chunk}\n",residue(part));}
            body+=&format!("theorem dot{c}_{which} : (∑ r : Fin 108, q{c} r * WitnessPointData.weights{which} r) = ({}:M) := by\n  rw [sum108, dot{c}_{which}_0, dot{c}_{which}_1, dot{c}_{which}_2, dot{c}_{which}_3]\n  decide\n#print axioms dot{c}_{which}\n",residue(obs[c][which]));
        }
        for (channel,ks,offset) in [("wr",vec![0,1,2,3,4,5],3),("wg",vec![0,1,2,3,5],10)]{for k in ks{body+=&format!("theorem poly{c}_{channel}_{k} : polyCoeff quarter q{c} {channel} {k} = ({}:M) := by\n  rw [poly_slots quarter q{c} {channel} ⟨{k},by decide⟩]\n  decide\n#print axioms poly{c}_{channel}_{k}\n",residue(obs[c][offset+k]));}}
        for(i,&r)in rows.iter().enumerate(){let calc=if r<3{format!("dot{c}_{r}")}else if r<10{format!("poly{c}_wr_{}",r-3)}else{format!("poly{c}_wg_{}",r-10)};
            body+=&format!("theorem entry{i}_{c} : observation ResidualPins.order ResidualPins.inactive half quarter (7:M) 5 (-5) 5 7 WitnessPointData.z (SourceResidualPolynomial.rootCoefficients half WitnessRootData.roots) {r} ({c}:Fin 13) = matrix {i} {c} := by\n  simp only [observation, quotient{c}, Nat.reduceEqDiff, Nat.reduceLT, ite_false, ite_true, Nat.reduceSub, WitnessPointData.point_weight0, WitnessPointData.point_weight1, WitnessPointData.point_weight2]\n");
            if r>=3{body+=if r<10{"  rw [wr_stage]\n"}else{"  rw [wg_stage]\n"};}
            body+=&format!("  exact {calc}\n#print axioms entry{i}_{c}\n");
        }body+=end;files.insert(format!("WitnessEntryColumn{c:02}.lean"),body);bridge+=&format!("import AspisV8R19.WitnessEntryColumn{c:02}\n");
    }
    bridge+=ns;bridge+="theorem minor_matrix : minor ResidualPins.order ResidualPins.inactive half quarter (7:M) 5 (-5) 5 7 WitnessPointData.z (SourceResidualPolynomial.rootCoefficients half WitnessRootData.roots) = matrix := by\n  funext i j\n  fin_cases i <;> fin_cases j\n";for i in 0..13{for c in 0..13{bridge+=&format!("  · exact entry{i}_{c}\n");}}bridge+="#print axioms minor_matrix\n";bridge+=end;files.insert("WitnessEntryBridge.lean".into(),bridge);
    let matrix:Vec<Vec<K>>=rows.iter().map(|&r|(0..13).map(|c|obs[c][r]).collect()).collect();let mut reduced=matrix.clone();let mut inverse=vec![vec![K::ZERO;13];13];for i in 0..13{inverse[i][i]=K::ONE;}
    for c in 0..13{let pivot=(c..13).find(|&r|reduced[r][c]!=K::ZERO).expect("singular witness");reduced.swap(pivot,c);inverse.swap(pivot,c);let scale=reduced[c][c].inv();for j in 0..13{reduced[c][j]=reduced[c][j].mul(scale);inverse[c][j]=inverse[c][j].mul(scale);}for r in 0..13{if r==c{continue;}let factor=reduced[r][c];for j in 0..13{reduced[r][j]=reduced[r][j].sub(factor.mul(reduced[c][j]));inverse[r][j]=inverse[r][j].sub(factor.mul(inverse[c][j]));}}}
    for i in 0..13{for j in 0..13{assert_eq!((0..13).fold(K::ZERO,|s,k|s.add(matrix[i][k].mul(inverse[k][j]))),if i==j{K::ONE}else{K::ZERO});}}
    let inverse_data=format!("{header}import AspisV8R19.WitnessEntryData\nimport AspisV8R19.ResidualNonsingular\n{ns}def inverseMatrix : Matrix (Fin 13) (Fin 13) M := fun i j =>\n  (({:?} : List (List Nat)).getD i.val []).getD j.val 0\n{end}",inverse.iter().map(|r|residues(r)).collect::<Vec<_>>());files.insert("WitnessInverseData.lean".into(),inverse_data);
    let mut finish=String::from(header);finish+="import AspisV8R19.WitnessEntryBridge\n";
    for i in 0..13{files.insert(format!("WitnessInverseRow{i:02}.lean"),format!("{header}import AspisV8R19.WitnessInverseData\n{ns}theorem inverse_row{i} (j : Fin 13) : (matrix*inverseMatrix) {i} j = (1:Matrix (Fin 13) (Fin 13) M) {i} j := by\n  fin_cases j <;> (rw [Matrix.mul_apply]; decide)\n#print axioms inverse_row{i}\n{end}"));finish+=&format!("import AspisV8R19.WitnessInverseRow{i:02}\n");}
    finish+=ns;finish+="theorem matrix_right_inverse : matrix*inverseMatrix=1 := by\n  funext i j\n  fin_cases i\n";for i in 0..13{finish+=&format!("  · exact inverse_row{i} j\n");}
    finish+="theorem matrix_det_ne_zero : matrix.det ≠ 0 := by\n  letI : Nontrivial M := ⟨⟨0,1,by decide⟩⟩\n  exact ResidualNonsingular.right_inverse_det_ne_zero matrix inverseMatrix matrix_right_inverse\n";
    let mut assignment:Vec<u32>=(2..12).collect();assignment.extend([5,7,2,3]);assignment.extend(1..23);
    finish+=&format!("def assignment : Fin 36 → M := PointWeightCertificate.vector {assignment:?}\n");
    finish+="theorem assigned_matrix : SourceResidualPolynomial.assignedMinor half quarter assignment = matrix := by\n  have hz : (fun i : Fin 10 => assignment ⟨i.val,by omega⟩) = WitnessPointData.z := by\n    funext i\n    fin_cases i <;> decide\n  have hr : (fun i : Fin 22 => assignment ⟨14+i.val,by omega⟩) = WitnessRootData.roots := by\n    funext i\n    fin_cases i <;> decide\n  unfold SourceResidualPolynomial.assignedMinor SourceResidualPolynomial.normalizedMinor\n  rw [hz,hr]\n  change minor ResidualPins.order ResidualPins.inactive half quarter (7:M) 5 (-5) 5 7 WitnessPointData.z (SourceResidualPolynomial.rootCoefficients half WitnessRootData.roots) = matrix\n  exact minor_matrix\ntheorem assigned_det_ne_zero : (SourceResidualPolynomial.assignedMinor half quarter assignment).det ≠ 0 := by\n  rw [assigned_matrix]\n  exact matrix_det_ne_zero\ntheorem restricted_polynomial_ne_zero : (SourceResidualPolynomial.polyMinor half quarter).det ≠ 0 :=\n  ResidualNonsingular.polynomial_nonzero half quarter assignment assigned_det_ne_zero\n";
    for name in["matrix_right_inverse","matrix_det_ne_zero","assigned_matrix","assigned_det_ne_zero","restricted_polynomial_ne_zero"]{finish+=&format!("#print axioms {name}\n");}finish+=end;files.insert("WitnessNonzero.lean".into(),finish);
    for(n,v)in &files{if checking{assert_eq!(std::fs::read_to_string(out.join(n)).unwrap(),*v,"generated drift: {n}");}else{std::fs::write(out.join(n),v).unwrap();}}
    println!("R40_ENTRY_GENERATOR mode={} files={} low_weight_checks=216 quotient_checks=1404 source_observation_checks=208 retained_minor_checks=169 slot_negative_columns={} full_privacy=false",args[1],files.len(),negative);
}
